    $sql->Consultar('camaras','*',"local_id=".$_SESSION["local_id"]." and sistema=0 and encendida=1","descripcion asc",false);    

    if($sql->num>0){
        do {
            $camara_id=$sql->row["id"];
            $url_conexion=$sql->row["url_conexion"];

            if(!isset($_GET["id"]) or $_GET["id"]==""){
                $cmd=RUTA_PYTHON." ".RUTA_PROYECTO."motor/dofoto.py ".$camara_id." '".$url_conexion."' '".RUTA_PROYECTO."'";
                //echo "<br /><br />->".$cmd."<-<br /><br />";
                exec($cmd);
                sleep(2);
                exec("chmod -R 777 ".RUTA_PROYECTO."admin/fotos_camara/".$camara_id.".png");    
            }
            
            echo "<td><img style='cursor:pointer' onclick=\"location.href='?page=camaras&id=".$sql->row["id"]."'\" src='fotos_camara/".$camara_id.".png'><br />".$sql->row["descripcion"]."</td>";

            if($i==$limite_linea){
                echo "</tr><tr>";
            }
            $i++;

        }while($sql->Siguiente());
    }
    for($j=$i;$j<$limite_linea;$j++){
        echo "<td></td>";
    }



